 "content": "def transform(grid):
    """Color cells strictly between matching marker cells in rows/columns."""
    h, w = len(grid), len(grid[0])
    g = [row[:] for row in grid]
    vals = {v for row in grid for v in row}
    # The uniform background is the most common value; other value(s) are markers.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    markers = {v for v in vals if v != bg}
    if not markers:
        return g
    marker = next(iter(markers))
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == marker]
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    g[r][c] = 3
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == marker]
        for a, b in zip(rs, rs[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    g[r][c] = 3
    return g
